<script setup lang="ts">
import {computed,ref} from 'vue';
import type {ResumeLayout} from './api';
import {resumeTemplates,templateName} from './resumeTemplates';
const props=defineProps<{layout:ResumeLayout}>();
const tab=ref<'template'|'text'|'style'|'spacing'>('template');
const tabs=[{id:'template',name:'模板',icon:'M3 3h18v18H3z M3 8h18 M9 8v13'},{id:'text',name:'文字',icon:'M4 5V3h16v2 M12 3v18 M8 21h8'},{id:'style',name:'样式',icon:'M12 3a9 9 0 1 0 0 18h2a2 2 0 0 0 1-4l-1-1a2 2 0 0 1 2-3h2a3 3 0 0 0 3-3 9 9 0 0 0-9-7Z M7 8h.1 M12 6h.1 M17 8h.1 M6 13h.1'},{id:'spacing',name:'间距',icon:'M3 6h18 M3 12h18 M3 18h18 M8 3v6 M16 9v6 M10 15v6'}] as const;
const colors=[['深蓝','#244f63'],['橙色','#c65c19'],['绿色','#047857'],['紫色','#7c3aed'],['红色','#dc2626'],['青色','#0e7490'],['灰色','#6b7280'],['黑色','#202428']];
const percent=computed(()=>Math.round(props.layout.fontSize*10));
function size(event:Event){const value=Number((event.target as HTMLInputElement).value);if(Number.isFinite(value)&&value>=9&&value<=12)props.layout.fontSize=value;else(event.target as HTMLInputElement).value=String(props.layout.fontSize);}
function resetSpacing(){Object.assign(props.layout,{lineHeight:1.68,sectionGapMm:4,marginMm:16});Object.assign(props.layout.presentation,{marginHorizontalMm:16,marginTopMm:16,marginBottomMm:16,entryGapMm:3,paragraphGapMm:.9});}
function resetStyle(){Object.assign(props.layout.presentation,{accentColor:'#244f63',alignment:'left',contactStyle:'plain',headingStyle:'template'});}
</script>
<template>
 <div class="layout-controls">
  <nav class="layout-tabs" role="tablist" aria-label="简历排版设置"><button v-for="item in tabs" :key="item.id" :id="'layout-tab-'+item.id" role="tab" :aria-selected="tab===item.id" :aria-controls="'layout-panel-'+item.id" @click="tab=item.id"><svg viewBox="0 0 24 24" aria-hidden="true"><path :d="item.icon"/></svg>{{item.name}}</button></nav>
  <section :id="'layout-panel-'+tab" role="tabpanel" :aria-labelledby="'layout-tab-'+tab" :data-testid="'layout-'+tab"><h2>{{tabs.find(item=>item.id===tab)?.name}}设置</h2>
