    <label class="form-label">图片位置<select v-model="layout.swapImages" aria-label="页眉布局"><option :value="false">证件照在前 · 右上角学校 Logo</option><option :value="true">学校 Logo 在前 · 右上角证件照</option></select></label>
   </template>
   <template v-else-if="tab==='text'">
    <p class="layout-caption">简历语言</p><div class="layout-choices"><button :aria-pressed="layout.presentation.language==='zh'" @click="layout.presentation.language='zh'">中文</button><button :aria-pressed="layout.presentation.language==='en'" @click="layout.presentation.language='en'">English</button></div><p class="layout-note">切换信息标签和续页提示的语言，正文按你的输入显示。</p>
    <p class="layout-caption">字体</p><div class="layout-fonts"><button :aria-pressed="layout.font==='sans'" aria-label="黑体" @click="layout.font='sans'"><strong>黑体</strong><span>中文技术岗 · Spring Boot</span><small>Noto Sans SC</small></button><button :aria-pressed="layout.font==='serif'" aria-label="宋体" class="font-serif" @click="layout.font='serif'"><strong>宋体</strong><span>中文技术岗 · Spring Boot</span><small>Noto Serif SC</small></button></div><p class="layout-note">字体随应用提供，预览和 PDF 使用同一套字体。</p>
    <div class="layout-range-heading"><label for="layout-size">字号</label><output>{{percent}}%</output></div><input id="layout-size" aria-label="字号比例" type="range" min="90" max="120" step="1" :value="percent" @input="layout.fontSize=Number(($event.target as HTMLInputElement).value)/10"><div class="layout-choices"><button :aria-pressed="layout.fontSize===9.5" @click="layout.fontSize=9.5">小 <small>95%</small></button><button :aria-pressed="layout.fontSize===10" @click="layout.fontSize=10">标准 <small>100%</small></button><button :aria-pressed="layout.fontSize===11" @click="layout.fontSize=11">大 <small>110%</small></button></div><label class="layout-font-point">正文字号<input aria-label="正文字号" type="number" min="9" max="12" step=".1" :value="layout.fontSize" @change="size">pt</label>
   </template>
