    <div class="layout-range"><div class="layout-range-heading"><label for="layout-top">上边距</label><output>{{layout.presentation.marginTopMm}} mm</output></div><input id="layout-top" v-model.number="layout.presentation.marginTopMm" aria-label="上页边距" type="range" min="8" max="32" step="1"><div class="layout-range-ends"><span>窄</span><span>宽</span></div></div>
