    <details class="layout-extra"><summary>更多间距</summary><div class="layout-range"><div class="layout-range-heading"><label for="layout-entry-gap">条目间距</label><output>{{layout.presentation.entryGapMm}} mm</output></div><input id="layout-entry-gap" v-model.number="layout.presentation.entryGapMm" aria-label="条目间距" type="range" min="0" max="8" step=".5"></div><div class="layout-range"><div class="layout-range-heading"><label for="layout-paragraph-gap">段落与列表间距</label><output>{{layout.presentation.paragraphGapMm}} mm</output></div><input id="layout-paragraph-gap" v-model.number="layout.presentation.paragraphGapMm" aria-label="段落与列表间距" type="range" min="0" max="4" step=".1"></div></details><button class="layout-reset" @click="resetSpacing">恢复默认间距</button>
