ate-columns:repeat(4,1fr);gap:12px 14px}.layout-colors button{padding:3px;place-self:center;width:43px;height:43px;border-radius:50%;border:2px solid transparent;background:transparent!important}.layout-colors button[aria-pressed=true]{border-color:var(--ui-accent)}.layout-colors button span{display:block;border-radius:50%;width:100%;height:100%;background:var(--swatch)}.layout-color-value{display:flex;align-items:center;gap:10px;font-size:11px;color:var(--ui-muted);margin:17px 0}.layout-color-value input{width:35px;height:28px;padding:1px}.layout-color-value code{margin-left:auto;font:11px Arial,sans-serif}.layout-controls .form-label{margin-top:24px}.layout-controls select{margin-top:9px}.layout-range{margin:27px 0 33px}.layout-range-ends{display:flex;justify-content:space-between;color:var(--ui-muted);font-size:10px}.layout-extra{margin:0 0 25px;color:var(--ui-muted);font-size:12px}.layout-extra summary{cursor:pointer}.layout-reset{width:100%;padding:12px!important;font-size:12px!important}.layout-template-cards{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:28px}.layout-template-cards button{padding:14px 10px;text-align:left;min-width:0}.layout-template-cards strong{display:block;font-size:12px;margin-top:12px}.layout-template-cards small{display:block;font-weight:400;line-height:1.7;font-size:10px;margin-top:5px;color:var(--ui-muted)}.layout-mini{display:grid;grid-template-columns:16px 1fr 16px;align-content:start;gap:7px 4px;padding:12px 9px;width:100%;height:132px;background:#fff;border:1px solid #dce3ed;box-shadow:0 2px 3px #0001}.layout-mini i{height:20px;background:#dce6ea}.layout-mini b{height:6px;margin-top:3px;background:#244f63}.layout-mini.banner{grid-template-columns:1fr 16px 16px}.layout-mini em{display:block;grid-column:1/-1;height:16px;border-top:2px solid #244f63;border-bottom:1px solid #edf0f2;margin-top:6px}.layout-mini em+em{height:22px}
</style>
