.layout-mini .mini-contacts{display:none}.layout-mini.banner b{grid-column:1;grid-row:1}.layout-mini.banner .mini-photo{grid-column:2;grid-row:1}.layout-mini.banner .mini-logo{grid-column:3;grid-row:1}
